@Service @Transactional(rollbackFor=Exception.class)
public class OfficeService {
 private final OfficeSheetGuard sheetGuard;private final OfficeSheetAccessService sheetAccess;@org.springframework.beans.factory.annotation.Value("${app.frontend.base-url:http://localhost:5173}") private String frontend;private final OfficeSettings settings;private final OfficeTokens tokens;private final OfficeSessionRepository sessions;private final FileSuiteService files;private final FileOperationService operations;private final UserRepository users;private final OfficeDownloadClient downloads;private final ObjectMapper json;
 public OfficeService(OfficeSettings settings,OfficeTokens tokens,OfficeSessionRepository sessions,FileSuiteService files,FileOperationService operations,UserRepository users,OfficeDownloadClient downloads,ObjectMapper json,OfficeSheetAccessService sheetAccess,OfficeSheetGuard sheetGuard){this.sheetGuard=sheetGuard;this.sheetAccess=sheetAccess;this.settings=settings;this.tokens=tokens;this.sessions=sessions;this.files=files;this.operations=operations;this.users=users;this.downloads=downloads;this.json=json;}
 @org.springframework.beans.factory.annotation.Autowired private OfficeCellLocks cellLocks;
 @org.springframework.beans.factory.annotation.Autowired private OfficePasswordVault passwords;
 public Map<String,Object> verifyPassword(Long id,String password)throws IOException{files.accessManagedItem(id);FileItem f=files.officeLock(id);passwords.verify(id,password,java.nio.file.Files.readAllBytes(files.officeSource(f,f.getCurrentVersion()).path()),ext(f));files.officeEvent(f,"FILE_OPENING_PASSWORD_REMEMBERED");return Map.of("verified",true); }
 private FileItem cellLockFile(Long id){var file=files.officeLock(id);var view=files.officeView(file);if(!"xlsx".equals(ext(file))||!view.canEdit()||!Set.of("OWNER","MANAGER").contains(view.access())||!operations.allows(files.currentUser(),"FILE_MANAGE_ACCESS"))throw new ResponseStatusException(FORBIDDEN,"Only the workbook owner, ADMIN or an authorized editing manager can lock cells");return file;}
 public Map<String,Object> cellLockStatus(Long id,String sheet)throws IOException{var file=cellLockFile(id);return cellLocks.status(passwords.decode(id,java.nio.file.Files.readAllBytes(files.officeSource(file,file.getCurrentVersion()).path()),"xlsx"),sheet,file.getCurrentVersion());}
 public Object cellLocks(Long id,OfficeCellLocks.Request request)throws IOException{
  configured();var file=cellLockFile(id);var user=files.currentUser();var s=session(request.sessionId());
  if(!s.getFile().getId().equals(id)||!Boolean.TRUE.equals(participants(s).get(uid(user))))throw new ResponseStatusException(FORBIDDEN,"Open this workbook in an authorized editing session first");
  if(participants(s).entrySet().stream().anyMatch(e->!e.getKey().equals(uid(user))&&Boolean.TRUE.equals(e.getValue())))throw new ResponseStatusException(CONFLICT,"Other editing participants must close this workbook before changing standard cell locks. Save and reopen it as the owner.");
  if(request.expectedVersion()!=file.getCurrentVersion()||s.getSavedVersion()!=file.getCurrentVersion())throw new ResponseStatusException(CONFLICT,"The saved workbook changed. Close this password prompt and select the cells again.");
  byte[] original=java.nio.file.Files.readAllBytes(files.officeSource(file,file.getCurrentVersion()).path());
  byte[] changed=cellLocks.apply(passwords.decode(id,original,"xlsx"),request);sheetAccess.verifyCheckpoint(file,changed);if(OfficePasswordVault.encrypted(original))changed=passwords.encode(id,changed);
  files.officeAppend(file,changed,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",s.getDocumentKey(),file.getCurrentVersion());
  s.setSavedVersion(file.getCurrentVersion());s.setState("CLOSED");file.setCollaborationRoom(null);file.setCollaborationLeaseUntil(null);
  files.officeEvent(file,(request.locked()?"CELLS_LOCKED ":"CELLS_UNLOCKED ")+request.sheet()+"!"+request.range());return files.officeView(file);
 }
 private void configured(){if(!settings.isEnabled())throw new ResponseStatusException(SERVICE_UNAVAILABLE,"ONLYOFFICE is not enabled. Start the local Document Server and configure the connector.");OfficeDownloadClient.safeOrigin(settings.getBrowserUrl());OfficeDownloadClient.safeOrigin(settings.getServerUrl());OfficeDownloadClient.safeOrigin(settings.getConnectorUrl());}
 private String ext(FileItem f){String name=f.getName();String ext=name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);if(!Set.of("docx","xlsx","pptx").contains(ext))throw new ResponseStatusException(UNPROCESSABLE_ENTITY,"Native editing supports DOCX, XLSX and PPTX. Download the original for other Office formats.");return ext;}
 private static String uid(User u){return "eac-"+u.getId();}
 private Map<String,Boolean> participants(OfficeSession s){try{return json.readValue(s.getParticipants(),new TypeReference<Map<String,Boolean>>(){});}catch(Exception e){throw new ResponseStatusException(CONFLICT,"Invalid document session participant state");}}
 private void participants(OfficeSession s,Map<String,Boolean> p){try{s.setParticipants(json.writeValueAsString(p));}catch(Exception e){throw new IllegalStateException(e);}}
 private OfficeSession session(String id){return sessions.findById(id).filter(s->"OPEN".equals(s.getState())&&s.getExpiresAt().isAfter(Instant.now())).orElseThrow(()->new ResponseStatusException(CONFLICT,"This document session ended. Reopen the file."));}
 private void lease(OfficeSession s){s.setExpiresAt(Instant.now().plusSeconds(7200));if(s.isWritable()){s.getFile().setCollaborationRoom("onlyoffice:"+s.getDocumentKey());s.getFile().setCollaborationLeaseUntil(s.getExpiresAt());}}
 public Map<String,Object> availability(){files.currentUser();return Map.of("enabled",settings.isEnabled(),"protectedRangesVerified",settings.isProtectedRangesVerified());}
 public Map<String,Object> config(Long id)throws IOException{return config(id,frontend);} public Map<String,Object> config(Long id,String origin)throws IOException{configured();User user=files.currentUser();FileItem file=files.officeLock(id);var view=files.officeView(file);if(file.isFolder())throw new ResponseStatusException(BAD_REQUEST,"Open a document, not a folder");String ext=ext(file);if(ext.equals("xlsx"))sheetAccess.assertOpen(file,user);var previous=sessions.findByFile_IdAndStateOrderByCreatedAtDesc(id,"OPEN");OfficeSession s=previous.stream().filter(x->x.getExpiresAt().isAfter(Instant.now())&&(x.isWritable()||!view.canEdit())).findFirst().orElse(null);if(s==null){if(file.getCollaborationLeaseUntil()!=null&&file.getCollaborationLeaseUntil().isAfter(Instant.now()))throw new ResponseStatusException(CONFLICT,"Close the existing editing session before starting ONLYOFFICE");s=new OfficeSession();s.setId(UUID.randomUUID().toString());s.setFile(file);s.setDocumentKey("eac-"+id+"-"+UUID.randomUUID());s.setSavedVersion(file.getCurrentVersion());s.setWritable(view.canEdit());}if(s.getSavedVersion()!=file.getCurrentVersion())throw new ResponseStatusException(CONFLICT,"The original file changed outside this Office session. Reopen after the active session closes.");Map<String,Boolean> p=participants(s);p.merge(uid(user),view.canEdit(),(before,now)->before||now);participants(s,p);lease(s);sessions.saveAndFlush(s);String base=settings.getConnectorUrl().replaceAll("/$","");String source=tokens.sign(Map.of("purpose","office-source","session",s.getId(),"user",user.getId(),"version",s.getSavedVersion()));boolean manager=Set.of("OWNER","MANAGER").contains(view.access())&&operations.allows(user,"FILE_MANAGE_ACCESS");Map<String,Object> permissions=new LinkedHashMap<>();permissions.put("edit",view.canEdit());permissions.put("download",operations.allows(user,"FILE_DOWNLOAD")&&files.downloadAllowed(file,user)&&sheetGuard.wholeWorkbookAllowed(file,user));permissions.put("print",operations.allows(user,"FILE_DOWNLOAD")&&files.downloadAllowed(file,user)&&sheetGuard.wholeWorkbookAllowed(file,user));permissions.put("copy",operations.allows(user,"FILE_DOWNLOAD")&&files.downloadAllowed(file,user)&&sheetGuard.wholeWorkbookAllowed(file,user));permissions.put("review",view.canEdit());permissions.put("comment",view.canEdit());permissions.put("protect",manager);permissions.put("chat",false);Map<String,Object> config=new LinkedHashMap<>();config.put("documentType",ext.equals("xlsx")?"cell":ext.equals("pptx")?"slide":"word");config.put("type","desktop");config.put("width","100%");config.put("height","100%");config.put("document",Map.of("fileType",ext,"key",s.getDocumentKey(),"title",file.getName(),"url",base+"/api/onlyoffice/source?token="+source,"permissions",permissions));config.put("editorConfig",Map.of("mode",view.canEdit()?"edit":"view","lang","en","callbackUrl",base+"/api/onlyoffice/callback/"+s.getId(),"user",Map.of("id",uid(user),"name",Objects.toString(user.getName(),user.getUserName())),"coEditing",Map.of("mode","fast","change",false),"customization",Map.of("forcesave",true,"autosave",true)));if(ext.equals("xlsx")){var editorConfig=new LinkedHashMap<String,Object>((Map<String,Object>)config.get("editorConfig"));editorConfig.put("plugins",sheetPlugin(file,user,manager,origin));config.put("editorConfig",editorConfig);}config.put("token",tokens.sign(config));files.officeEvent(file,"ONLYOFFICE_SESSION_OPEN");return Map.of("sessionId",s.getId(),"scriptUrl",settings.getBrowserUrl().replaceAll("/$","")+"/web-apps/apps/api/documents/api.js","config",config,"canManageProtection",manager,"protectedRangesVerified",settings.isProtectedRangesVerified());}
 private Map<String,Object> sheetPlugin(FileItem file,User user,boolean manager,String origin){
  String guid="asc.{B785C60D-E5F1-48D1-A624-2BF8EAC50001}";User owner=file.getOwner();String ownerId=uid(owner);
  String frontendOrigin=java.net.URI.create(frontend).resolve("/").toString().replaceAll("/$","");
  if(origin!=null){var uri=java.net.URI.create(origin);boolean local=settings.getBrowserUrl().startsWith("http://localhost:")&&Set.of("localhost","127.0.0.1").contains(uri.getHost())&&"http".equals(uri.getScheme());if(origin.equals(frontendOrigin)||local)frontendOrigin=origin;}
  List<Map<String,String>> people=new ArrayList<>(manager?candidates(file.getId()):List.of());
  if(manager&&people.stream().noneMatch(person->ownerId.equals(person.get("id"))))people.add(Map.of("id",ownerId,"name",Objects.toString(owner.getName(),owner.getUserName()),"email",Objects.toString(owner.getEmail(),"")));
  var admins=sheetAccess.administrators().stream().map(admin->Map.of("id",uid(admin),"name",Objects.toString(admin.getName(),admin.getUserName()),"access","CanEdit")).toList();
  return Map.of("autostart",List.of(guid),"pluginsData",List.of(settings.getBrowserUrl().replaceAll("/$","")+"/sdkjs-plugins/{B785C60D-E5F1-48D1-A624-2BF8EAC50001}/config.json?v=11"),"options",Map.of(guid,Map.of("userId",uid(user),"ownerId",ownerId,"canManage",manager,"employees",people,"adminOverride",FileSuiteService.admin(user),"administrators",admins,"bridgeNonce",UUID.randomUUID().toString(),"frontendOrigin",frontendOrigin)));
 }
 public Map<String,Object> save(String id)throws IOException{configured();User user=files.currentUser();OfficeSession s=session(id);FileItem f=s.getFile();var view=files.officeView(f);if(!s.isWritable()||!view.canEdit()||!Boolean.TRUE.equals(participants(s).get(uid(user))))throw new ResponseStatusException(FORBIDDEN,"Only a current editing participant can save this workbook");boolean requested=downloads.requestSave(s.getDocumentKey());return Map.of("requested",requested,"version",f.getCurrentVersion());}
 @FunctionalInterface interface Task<T>{T run()throws IOException;}
 private <T>T asUser(long id,Task<T> task)throws IOException{User user=users.findById(id).filter(u->Boolean.TRUE.equals(u.getEnabled())&&(u.getEmployee()==null||!Boolean.FALSE.equals(u.getEmployee().getActive()))).orElseThrow(()->new ResponseStatusException(FORBIDDEN,"Document participant is no longer active"));var before=SecurityContextHolder.getContext().getAuthentication();try{SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user.getUserName(),"",List.of(new SimpleGrantedAuthority(user.getRole().getName()))));files.currentUser();return task.run();}finally{SecurityContextHolder.getContext().setAuthentication(before);}}
 public FileSuiteService.Download source(String token)throws IOException{configured();var claims=tokens.verify(token);if(!"office-source".equals(claims.get("purpose")))throw new ResponseStatusException(UNAUTHORIZED,"Invalid document retrieval scope");OfficeSession s=session(claims.get("session",String.class));long user=((Number)claims.get("user")).longValue(),version=((Number)claims.get("version")).longValue();if(!participants(s).containsKey("eac-"+user))throw new ResponseStatusException(FORBIDDEN,"Unknown document participant");if(version>s.getSavedVersion())throw new ResponseStatusException(CONFLICT,"Invalid document source version");return asUser(user,()->files.officeSource(s.getFile(),s.getSavedVersion()));}
 public Map<String,Object> heartbeat(String id){User user=files.currentUser();OfficeSession s=session(id);FileItem f=files.officeLock(s.getFile().getId());var v=files.officeView(f);if(f.getName().toLowerCase(Locale.ROOT).endsWith(".xlsx"))sheetAccess.assertOpen(f,user);Boolean editable=participants(s).get(uid(user));if(editable==null||editable&&!v.canEdit())throw new ResponseStatusException(FORBIDDEN,"Your document access changed. Close and reopen the file.");lease(s);return Map.of("version",f.getCurrentVersion(),"state",s.getState(),"needsPassword",passwords.needsPassword(f.getId()));}
 public List<Map<String,String>> candidates(Long id){FileItem f=files.accessManagedItem(id);return users.findByEnabledTrue().stream().filter(u->u.getEmployee()!=null&&!Boolean.FALSE.equals(u.getEmployee().getActive())).filter(u->{try{return Set.of("OWNER","MANAGER","EDITOR").contains(Objects.toString(files.access(f,u,false),""))&&operations.allows(u,"FILE_EDIT");}catch(Exception e){return false;}}).map(u->Map.of("id",uid(u),"name",Objects.toString(u.getName(),u.getUserName()),"email",Objects.toString(u.getEmail(),""))).toList();}
 public void callback(String id,JsonNode signed)throws IOException{configured();OfficeSession found=sessions.findById(id).orElseThrow(()->new ResponseStatusException(NOT_FOUND,"Unknown document session"));FileItem f=files.officeLock(found.getFile().getId());OfficeSession s=sessions.findById(id).orElseThrow();if(!s.getDocumentKey().equals(signed.path("key").asText()))throw new ResponseStatusException(FORBIDDEN,"Document callback key mismatch");int status=signed.path("status").asInt(-1);if(!Set.of(1,2,3,4,6,7).contains(status))throw new ResponseStatusException(BAD_REQUEST,"Unknown document callback status");if(!"OPEN".equals(s.getState())){if(Set.of(2,4).contains(status)&&"CLOSED".equals(s.getState()))return;throw new ResponseStatusException(CONFLICT,"Document session is no longer open");}if(!s.getExpiresAt().isAfter(Instant.now()))throw new ResponseStatusException(CONFLICT,"Document session expired; original content retained");Map<String,Boolean> p=participants(s);for(var entry:p.entrySet()){long userId=Long.parseLong(entry.getKey().substring(4));asUser(userId,()->{var v=files.officeView(f);if(entry.getValue()&&!v.canEdit())throw new ResponseStatusException(FORBIDDEN,"A contributor's editing access was revoked; save blocked for review");return null;});}if(status==3||status==7){lease(s);return;}if(status==2||status==6){if(!s.isWritable())throw new ResponseStatusException(FORBIDDEN,"Read-only sessions cannot save");String actor=signed.path("users").path(0).asText();if(!Boolean.TRUE.equals(p.get(actor)))throw new ResponseStatusException(FORBIDDEN,"Save callback has no authorized editing contributor");String extension=ext(f);if(!extension.equals(signed.path("filetype").asText(extension)))throw new ResponseStatusException(UNPROCESSABLE_ENTITY,"Saved format changed; original content retained");byte[] data=downloads.fetch(signed.path("url").asText());byte[] verified=passwords.decode(f.getId(),data,extension);OfficeDownloadClient.validatePackage(verified,extension);if(extension.equals("xlsx"))sheetAccess.verifyCheckpoint(f,verified);String checksum;try{checksum=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}catch(Exception e){throw new IllegalStateException(e);}if(!checksum.equals(s.getLastChecksum())){String media=extension.equals("xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":extension.equals("pptx")?"application/vnd.openxmlformats-officedocument.presentationml.presentation":"application/vnd.openxmlformats-officedocument.wordprocessingml.document";asUser(Long.parseLong(actor.substring(4)),()->{files.officeAppend(f,data,media,s.getDocumentKey(),s.getSavedVersion());return null;});s.setSavedVersion(f.getCurrentVersion());s.setLastChecksum(checksum);}}if(status==4){s.setExpiresAt(Instant.now().plusSeconds(120));if(Objects.equals(f.getCollaborationRoom(),"onlyoffice:"+s.getDocumentKey()))f.setCollaborationLeaseUntil(s.getExpiresAt());return;}if(status==2){s.setState("CLOSED");if(Objects.equals(f.getCollaborationRoom(),"onlyoffice:"+s.getDocumentKey())){f.setCollaborationRoom(null);f.setCollaborationLeaseUntil(null);}}else lease(s);}
}
